    void loginScreen(){ stopAutoRefresh(); ScrollView sv=new ScrollView(this); LinearLayout b=box(); b.setBackgroundColor(BG); b.setGravity(Gravity.CENTER_HORIZONTAL); sv.addView(b); ImageView logo=new ImageView(this); logo.setImageResource(getResources().getIdentifier("logo","drawable",getPackageName())); b.addView(logo,new LinearLayout.LayoutParams(dp(96),dp(96))); TextView title=tv("ShuttleX",28,TEXT,Typeface.BOLD); title.setGravity(Gravity.CENTER); b.addView(title); b.addView(tv("Native client for your current tournament environment.",14,MUTED,Typeface.NORMAL)); b.addView(tv("API: "+baseUrl(),12,MUTED,Typeface.NORMAL)); final EditText user=input("Username"); final EditText pass=input("Password"); pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD); Button login=btn("Login",PRIMARY); final TextView status=tv("",14,RED,Typeface.NORMAL); b.addView(user); b.addView(pass); b.addView(login); b.addView(status); login.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ JSONObject body=new JSONObject(); try{ body.put("username",user.getText().toString().trim()); body.put("password",pass.getText().toString()); }catch(Exception e){} status.setText("Signing in..."); rpc("login_user",body,new RpcCb(){ public void call(boolean ok,JSONObject res,String err){ if(!ok){ status.setText(err.indexOf("session")>=0?"Login session limit exceeded. Logout from another device first.":"Invalid username or password."); return;} token=res.optString("token"); username=res.optString("username"); displayName=res.optString("displayName"); isAdmin=res.optBoolean("isAdmin"); prefs.edit().putString("token",token).putString("username",username).putString("displayName",displayName).putBoolean("isAdmin",isAdmin).apply(); if(res.optBoolean("mustResetPassword")) resetScreen(true); else shell(); }}); }}); setContentView(sv); }

