    void shell(){ root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(BG); LinearLayout head=new LinearLayout(this); head.setOrientation(LinearLayout.HORIZONTAL); head.setGravity(Gravity.CENTER_VERTICAL); head.setPadding(dp(12),dp(8),dp(12),dp(8)); head.setBackground(bg(SURFACE,BORDER,0)); head.addView(tv("ShuttleX",22,TEXT,Typeface.BOLD),new LinearLayout.LayoutParams(0,-2,1)); Button profile=btn("Profile",PRIMARY); head.addView(profile); root.addView(head); HorizontalScrollView hsv=new HorizontalScrollView(this); hsv.setHorizontalScrollBarEnabled(false); tabButtons.clear(); LinearLayout nav=new LinearLayout(this); nav.setOrientation(LinearLayout.HORIZONTAL); nav.setPadding(dp(8),dp(6),dp(8),dp(6)); nav.setBackground(bg(SURFACE,BORDER,8)); String[] tabs=isAdmin?new String[]{"Tournament","Players","Teams","Schedule","Points","Users","Leaderboard","History"}:new String[]{"Tournament","Players","Teams","Schedule","Points","Leaderboard","History"}; for(int i=0;i<tabs.length;i++){ final String t=tabs[i]; Button nb=tabBtn(t,t.equals(activeView)); nb.setMinWidth(dp(112)); nb.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ selectTab(t); }}); tabButtons.add(nb); LinearLayout.LayoutParams nlp=new LinearLayout.LayoutParams(-2,-2); nlp.setMargins(dp(3),0,dp(3),0); nav.addView(nb,nlp); } hsv.addView(nav); root.addView(hsv,new LinearLayout.LayoutParams(-1,-2)); ScrollView sv=new ScrollView(this); content=box(); sv.addView(content); root.addView(sv,new LinearLayout.LayoutParams(-1,0,1)); setContentView(root); profile.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ showProfileDialog(); }}); if(appState.length()==0) fetchState(); else render(); startAutoRefresh(); }
    void fetchState(){ fetchState(false); }
    void fetchState(final boolean quiet){ if(fetchingState)return; fetchingState=true; if(!quiet&&content!=null){ content.removeAllViews(); content.addView(tv("Loading...",16,MUTED,Typeface.NORMAL)); } rpc("export_app_state",auth(),new RpcCb(){ public void call(boolean ok,JSONObject res,String err){ fetchingState=false; if(!ok){ clearSession(); loginScreen(); toast("Session expired or server unavailable."); return;} appState=res; parseRefs(); if(!quiet)render(); }}); }
    void startAutoRefresh(){ stopAutoRefresh(); autoRefreshRunnable=new Runnable(){ public void run(){ if(token.length()>0&&content!=null)fetchState(true); autoRefreshHandler.postDelayed(this,4000); }}; autoRefreshHandler.postDelayed(autoRefreshRunnable,4000); }
    void stopAutoRefresh(){ if(autoRefreshRunnable!=null){ autoRefreshHandler.removeCallbacks(autoRefreshRunnable); autoRefreshRunnable=null; } }
    void showProfileDialog(){ LinearLayout panel=box(); panel.addView(tv("Profile",22,TEXT,Typeface.BOLD)); panel.addView(tv(displayName.length()>0?displayName:username,16,TEXT,Typeface.BOLD)); panel.addView(tv(isAdmin?"Admin":"User",14,MUTED,Typeface.NORMAL)); panel.addView(tv("API: "+baseUrl(),12,MUTED,Typeface.NORMAL)); final AlertDialog dialog=new AlertDialog.Builder(this).setView(panel).create(); Button api=secondaryBtn("Change API URL"), change=btn("Change Password",PRIMARY), out=btn("Logout",RED); panel.addView(api); panel.addView(change); panel.addView(out); api.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ dialog.dismiss(); apiUrlScreen(); }}); change.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ dialog.dismiss(); resetScreen(false); }}); out.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ dialog.dismiss(); logout(); }}); dialog.show(); }
    void parseRefs(){ refs.clear(); try{ JSONArray a=new JSONArray(appState.optString("bt_tournaments_index_v1","[]")); for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i); refs.add(new TRef(o.optString("id"),o.optString("name",o.optString("id"))));} }catch(Exception e){} String id=prefs.getString("activeTournamentId",""); if(id.length()==0&&refs.size()>0)id=refs.get(0).id; loadTournament(id); }
    void loadTournament(String id){ tournament=null; if(id==null||id.length()==0)return; try{ tournament=new JSONObject(appState.optString("bt_tournament_v1_"+id,"")); prefs.edit().putString("activeTournamentId",id).apply(); }catch(Exception e){ tournament=null; } }
    void render(){ if(content==null)return; content.removeAllViews(); if("Players".equals(activeView))playersView(); else if("Teams".equals(activeView))teamsView(); else if("Schedule".equals(activeView))scheduleView(); else if("Points".equals(activeView))pointsView(); else if("Users".equals(activeView))usersView(); else if("Leaderboard".equals(activeView))globalLeaderboardView(); else if("History".equals(activeView))historyView(); else tournamentView(); }

